// Special Flags (Stored in EWRAM (sSpecialFlags), not in the SaveBlock)
#ifndef SPECIAL_FLAGS_START
#define SPECIAL_FLAGS_START                     0x4000
#endif
#ifndef FLAG_HIDE_MAP_NAME_POPUP
#define FLAG_HIDE_MAP_NAME_POPUP                (SPECIAL_FLAGS_START + 0x0)
#endif
#ifndef FLAG_DONT_TRANSITION_MUSIC
#define FLAG_DONT_TRANSITION_MUSIC              (SPECIAL_FLAGS_START + 0x1)
#endif
#ifndef FLAG_ENABLE_MULTI_CORRIDOR_DOOR
#define FLAG_ENABLE_MULTI_CORRIDOR_DOOR         (SPECIAL_FLAGS_START + 0x2)
#endif
#ifndef FLAG_SPECIAL_FLAG_UNUSED_0x4003
#define FLAG_SPECIAL_FLAG_UNUSED_0x4003         (SPECIAL_FLAGS_START + 0x3) // Unused Flag
#endif
#ifndef FLAG_STORING_ITEMS_IN_PYRAMID_BAG
#define FLAG_STORING_ITEMS_IN_PYRAMID_BAG       (SPECIAL_FLAGS_START + 0x4)
#endif
#ifndef FLAG_SAFE_FOLLOWER_MOVEMENT
#define FLAG_SAFE_FOLLOWER_MOVEMENT             (SPECIAL_FLAGS_START + 0x5) // When set, applymovement does not put the follower inside a pokeball
#endif
                                                                            // Also, scripted movements on the player will move follower(s), too
// FLAG_SPECIAL_FLAG_0x4005 - 0x407F also exist and are unused
#ifndef SPECIAL_FLAGS_END
#define SPECIAL_FLAGS_END                       (SPECIAL_FLAGS_START + 0x7F)
#endif
#ifndef NUM_SPECIAL_FLAGS
#define NUM_SPECIAL_FLAGS                       (SPECIAL_FLAGS_END - SPECIAL_FLAGS_START + 1)
#endif

